const currentTime = new Date().getHours(); // 0-23

function App() {
  return (
    <div className="container">
      {/* ternary, nothing in the false branch */}
      {currentTime > 12 ? <h1>Why are you still working?</h1> : null}

      {/* same result with && */}
      {currentTime > 12 && <h1>Why are you still working?</h1>}
    </div>
  );
}

